import { access, cp, mkdir, rm, writeFile } from "node:fs/promises";

const output = new URL("../.vercel/output/", import.meta.url);
const staticOutput = new URL("./static/", output);
const nativeConfig = new URL("./config.json", output);
const prerenderedOutput = new URL("../dist/client/", import.meta.url);

async function exists(path) {
  try {
    await access(path);
    return true;
  } catch {
    return false;
  }
}

// Preserve the complete deployment package generated by Vite on Vercel.
if (await exists(nativeConfig)) {
  console.log("Using Vercel output generated by the Vite adapter");
  process.exit(0);
}

if (!(await exists(prerenderedOutput))) {
  throw new Error(
    "The build produced neither .vercel/output/config.json nor dist/client",
  );
}

await rm(output, { recursive: true, force: true });
await mkdir(staticOutput, { recursive: true });
await cp(prerenderedOutput, staticOutput, {
  recursive: true,
});

await writeFile(
  nativeConfig,
  JSON.stringify(
    {
      version: 3,
      routes: [
        { src: "/", dest: "/index.html" },
        { src: "/work/?", dest: "/work/index.html" },
        { src: "/services/?", dest: "/services/index.html" },
        { src: "/about/?", dest: "/about/index.html" },
        { src: "/contact/?", dest: "/contact/index.html" },
        { handle: "filesystem" },
      ],
    },
    null,
    2,
  ),
);

console.log("Prepared Vercel Build Output API package in .vercel/output");